from functools import wraps

def my_decorator(func):
    @wraps(func)
    def wrapper(*args, **kwargs):
        """Wrapper docstring"""
        return func(*args, **kwargs)
    return wrapper

@my_decorator
def greet():
    """Greet docstring"""
    print("Hello!")

print(greet.__name__)  # Outputs 'greet' instead of 'wrapper'

